import 'package:flutter/material.dart';
import '../../data/models/models.dart';

/// Parcours annuel CE2 : trois trimestres, cinq domaines et exercices corrigés.
class Ce2CompletionScreen extends StatelessWidget {
  const Ce2CompletionScreen({super.key});
  static const _units = <_Unit>[
    _Unit('T1 • Français','Compréhension et types de phrases','Un texte est composé de phrases qui apportent des informations. Je repère le thème, les personnages, le lieu, le temps et les relations entre les actions. Une phrase peut être déclarative, interrogative ou exclamative.\n\nMéthode : lire une première fois pour comprendre l’ensemble, puis relire pour relever les indices. Distinguer le sujet du texte et les détails. Pour justifier une réponse, recopier un court passage utile. Respecter les signes de ponctuation et lire à voix haute en marquant les pauses.','Texte : « Kossi arrive tôt à l’école parce qu’il doit arroser le jardin. » La cause est son devoir d’arrosage.','Pourquoi Kossi arrive-t-il tôt ?',['Pour arroser le jardin','Pour rentrer chez lui','Pour acheter un livre'],0,'Le texte indique qu’il vient arroser le jardin.'),
    _Unit('T1 • Mathématiques','Numération jusqu’au million','La valeur d’un chiffre dépend de sa position : unités, dizaines, centaines, milliers, dizaines de milliers et centaines de milliers. Je lis les nombres par classes.\n\nSéparer les classes par groupes de trois chiffres en partant de la droite. Comparer deux nombres en regardant d’abord le nombre de chiffres, puis les chiffres de gauche à droite. Ranger dans l’ordre croissant ou décroissant et placer des nombres sur une droite graduée.','304 215 = 300 000 + 4 000 + 200 + 10 + 5.','Dans 582 641, quel est le chiffre des milliers ?',['2','8','6'],0,'Le chiffre des milliers est 2.'),
    _Unit('T1 • Anglais','Se présenter et parler de son quotidien','Pour se présenter, j’utilise I am…, I live in… et I like…. Pour parler d’une habitude, j’emploie des phrases simples au présent.\n\nConstruire une présentation en quatre phrases : nom, âge, lieu d’habitation et goûts. Exemple de structure : My name is…, I am … years old, I live in…, I like…. Écouter son camarade et poser une question courte : What do you like?','I live in Lomé. I like reading. = J’habite à Lomé. J’aime lire.','Que signifie « I like reading » ?',['Je lis hier','J’aime lire','Je vais lire demain'],1,'I like reading signifie j’aime lire.'),
    _Unit('T1 • Sciences','États de l’eau et changements','L’eau existe sous forme solide (glace), liquide et gazeuse (vapeur). La fusion fait passer du solide au liquide ; la solidification fait passer du liquide au solide ; l’évaporation forme de la vapeur.\n\nObserver les changements d’état dans des situations quotidiennes : glaçon qui fond, eau qui gèle, linge qui sèche. La quantité d’eau peut changer de forme sans que l’eau disparaisse. Ne jamais chauffer un récipient ni manipuler de l’eau bouillante sans adulte.','Un glaçon qui fond subit une fusion.','Comment appelle-t-on le passage de la glace à l’eau liquide ?',['Fusion','Solidification','Condensation'],0,'La fusion transforme un solide en liquide.'),
    _Unit('T1 • Éducation sociale','Communauté, droits et devoirs','Une communauté rassemble des personnes qui vivent ou travaillent ensemble. Chacun a des droits, mais aussi des devoirs : respecter les autres, les biens communs et les règles.\n\nLes droits protègent chaque personne ; les devoirs permettent à tous de vivre ensemble. Dans le quartier, respecter les lieux publics, aider une personne en difficulté et participer à la propreté sont des actes responsables. Un désaccord se règle par le dialogue.','Protéger les tables de l’école est un devoir collectif.','Quel comportement protège un bien commun ?',['Graver son nom sur la table','Casser une chaise','Utiliser le matériel avec soin'],2,'Prendre soin du matériel préserve le bien commun.'),
    _Unit('T2 • Français','Nature et fonction des mots','Le nom désigne ; le déterminant accompagne le nom ; l’adjectif le précise ; le verbe exprime une action ou un état. Le sujet commande l’accord du verbe.\n\nDans une phrase, le groupe nominal peut être enrichi par un adjectif. Le sujet peut être un nom ou un pronom. Pour accorder le verbe, repérer le sujet et vérifier s’il est singulier ou pluriel : l’enfant court / les enfants courent.','Dans « Les grands élèves travaillent », élèves est le nom, grands l’adjectif et travaillent le verbe.','Quel est le verbe dans « Les oiseaux chantent » ?',['oiseaux','chantent','les'],1,'Chantent exprime l’action.'),
    _Unit('T2 • Mathématiques','Multiplication et division posées','La multiplication posée permet de calculer le produit de nombres. La division partage ou forme des groupes égaux ; je vérifie le quotient par la multiplication.\n\nAvant de poser une multiplication, estimer le résultat. Multiplier d’abord par les unités puis par les dizaines en respectant le décalage. Dans une division exacte, quotient × diviseur = dividende. Si un reste existe, il doit être inférieur au diviseur.','24 × 13 = 24 × 10 + 24 × 3 = 312.','Combien font 36 × 4 ?',['124','144','164'],1,'36 × 4 = 144.'),
    _Unit('T2 • Anglais','Présent simple et vocabulaire courant','Au présent simple, le verbe décrit une habitude ou un fait. Avec he, she ou it, le verbe prend généralement -s à la forme affirmative.\n\nMémoriser les pronoms I, you, he, she, it, we, they. À la forme négative, employer do not ou does not suivi de la base verbale. Poser une question simple avec Do you…? et répondre Yes, I do / No, I don’t.','I play football. She plays football.','Complète : He … to school every day.',['go','goes','going'],1,'Avec he, on écrit goes au présent simple.'),
    _Unit('T2 • Sciences','Matière, mélanges et séparation','Un mélange réunit plusieurs substances. Certains mélanges sont homogènes, d’autres hétérogènes. La filtration peut séparer un solide insoluble d’un liquide.\n\nObserver sans goûter les mélanges du quotidien. La décantation laisse déposer les particules lourdes ; la filtration retient un solide dans un filtre ; le tamisage sépare des solides de tailles différentes. Certaines substances dissoutes ne sont pas retenues par un filtre ordinaire.','On peut retenir du sable avec un filtre et laisser passer l’eau.','Quelle technique permet de séparer du sable et de l’eau ?',['Filtration','Aimantation','Congélation'],0,'Le filtre retient le sable et laisse passer l’eau.'),
    _Unit('T2 • Éducation sociale','Hygiène publique et prévention','La santé dépend des gestes individuels et de l’environnement collectif. Éliminer les eaux stagnantes, utiliser les latrines et garder les alentours propres aide à prévenir certaines maladies.\n\nProtéger la santé collective demande de couvrir les récipients d’eau, vider les objets pouvant retenir la pluie et dormir sous une moustiquaire imprégnée selon les recommandations sanitaires. En cas de fièvre, prévenir un adulte et consulter un centre de santé.','Une cour propre et sans eaux stagnantes limite les lieux de reproduction des moustiques.','Quel geste contribue à prévenir le paludisme ?',['Laisser l’eau stagner','Vider les récipients inutilisés','Jeter les déchets dans les caniveaux'],1,'Supprimer les eaux stagnantes réduit les lieux de reproduction des moustiques.'),
    _Unit('T3 • Français','Conjugaison et rédaction organisée','Le temps du verbe situe l’action : présent, passé ou futur. Un récit suit souvent un ordre chronologique et utilise des connecteurs comme d’abord, ensuite, enfin.\n\nPour raconter un événement, préciser qui, où, quand et ce qui s’est passé. Employer les temps de manière cohérente et relier les étapes avec ensuite, puis, enfin. Relire pour vérifier que le lecteur comprend l’ordre des événements.','Hier, nous avons visité le musée. Demain, nous visiterons la bibliothèque.','Quel temps exprime une action qui aura lieu demain ?',['Passé','Présent','Futur'],2,'Demain annonce une action future.'),
    _Unit('T3 • Mathématiques','Fractions, décimaux et mesures','Une fraction représente une ou plusieurs parts d’une unité partagée en parts égales. Les nombres décimaux comportent une partie entière et une partie décimale.\n\nDans une fraction, le dénominateur indique le nombre total de parts égales et le numérateur le nombre de parts considérées. Lire les décimaux en distinguant unités, dixièmes et centièmes. Comparer d’abord les parties entières puis les parties décimales.','3/4 signifie trois parts sur quatre parts égales.','Quelle fraction représente une moitié ?',['1/2','1/3','1/4'],0,'Une moitié correspond à une part sur deux.'),
    _Unit('T3 • Anglais','Questions et réponses simples','Pour poser une question sur une habitude, on peut utiliser Do you…? Pour répondre, on dit Yes, I do ou No, I don’t. What, where, when et who demandent une information.\n\nAssocier les mots interrogatifs à leur sens : who (qui), where (où), when (quand), what (quoi/quel). Construire une question avec l’auxiliaire do, puis répondre par une phrase complète. Faire attention à l’ordre des mots.','Where do you live? — I live in Kara.','Quelle question demande un lieu ?',['Where do you live?','When do you leave?','Who is your friend?'],0,'Where demande où, donc un lieu.'),
    _Unit('T3 • Sciences','Électricité et sécurité','Un circuit électrique simple comprend une source, des fils et un récepteur. Le courant circule dans un circuit fermé. Il ne faut jamais manipuler une prise ou un fil dénudé.\n\nIdentifier la pile comme source, les fils comme conducteurs et la lampe comme récepteur. Un interrupteur ouvre ou ferme le circuit. Ne jamais utiliser le courant du secteur pour les expériences scolaires ; travailler uniquement avec du matériel pédagogique sécurisé sous la surveillance de l’enseignant.','Une pile reliée par des fils à une ampoule peut l’allumer si le circuit est fermé.','Quand l’ampoule peut-elle s’allumer ?',['Quand le circuit est fermé','Quand un fil est coupé','Sans pile'],0,'Le circuit doit être fermé et alimenté.'),
    _Unit('T3 • Éducation sociale','Citoyenneté et préparation au CM1','Être citoyen, c’est respecter les lois, les personnes et les biens communs, participer à la vie collective et connaître les symboles du pays. Je prépare la classe suivante en consolidant mes méthodes.\n\nJe peux montrer ma responsabilité en respectant les engagements, en protégeant l’environnement et en signalant un danger à un adulte. Pour préparer le CM1, je révise les opérations, la lecture, l’expression écrite et les notions scientifiques, puis je corrige mes erreurs.','Je révise les notions difficiles et je justifie mes réponses par une explication.','Quelle attitude montre la responsabilité ?',['Refuser toute règle','Respecter les biens communs','Détériorer le matériel'],1,'Respecter les biens communs est un comportement responsable.'),
  ];
  static int get unitCount => _units.length;
  static int get lessonCount => _units.length;
  static List<Exercise> assessmentExercisesForTerm(int term,{String? subjectName}) {
    final prefix='T$term •'; final result=<Exercise>[];
    for(var i=0;i<_units.length;i++){final u=_units[i];if(!u.title.startsWith(prefix))continue;if(subjectName!=null&&!_matches(u.title,subjectName))continue;result.add(Exercise(id:'ce2_t${term}_u${i}',lessonId:'ce2_t${term}_u${i}',question:u.question,options:u.options,correctIndex:u.answer,explanation:u.explanation));}
    return result;
  }
  static bool _matches(String title,String subject){final t=title.toLowerCase(),s=subject.toLowerCase();if(s.contains('français')||s.contains('francais'))return t.contains('français');if(s.contains('math'))return t.contains('mathématiques');if(s.contains('anglais')||s.contains('english'))return t.contains('anglais');if(s.contains('science'))return t.contains('sciences');if(s.contains('social')||s.contains('civique')||s.contains('morale'))return t.contains('éducation sociale');return false;}
  @override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Complément CE2 • Année complète')),body:ListView(padding:const EdgeInsets.all(16),children:[Card(child:Padding(padding:const EdgeInsets.all(16),child:Text('${Ce2CompletionScreen.unitCount} unités • ${Ce2CompletionScreen.lessonCount} leçons • 3 trimestres\nLis le cours, étudie l’exemple, réponds et consulte la correction.',style:const TextStyle(fontWeight:FontWeight.w600)))),for(final u in _units)_UnitTile(unit:u)]));
}
class _Unit{final String title,objective,content,example,question;final List<String> options;final int answer;final String explanation;const _Unit(this.title,this.objective,this.content,this.example,this.question,this.options,this.answer,this.explanation);}
class _UnitTile extends StatefulWidget{final _Unit unit;const _UnitTile({required this.unit});@override State<_UnitTile> createState()=>_UnitTileState();}
class _UnitTileState extends State<_UnitTile>{int? choice;bool checked=false;@override Widget build(BuildContext context){final u=widget.unit;return Card(margin:const EdgeInsets.only(bottom:10),child:ExpansionTile(title:Text(u.title,style:const TextStyle(fontWeight:FontWeight.bold)),subtitle:Text(u.objective),children:[Padding(padding:const EdgeInsets.fromLTRB(16,0,16,16),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(u.content),const SizedBox(height:8),Text('Exemple : ${u.example}',style:const TextStyle(fontStyle:FontStyle.italic)),const SizedBox(height:12),Text(u.question,style:const TextStyle(fontWeight:FontWeight.bold)),for(var i=0;i<u.options.length;i++)RadioListTile<int>(dense:true,contentPadding:EdgeInsets.zero,value:i,groupValue:choice,title:Text(u.options[i]),onChanged:checked?null:(v)=>setState(()=>choice=v)),FilledButton.tonal(onPressed:choice==null?null:()=>setState(()=>checked=true),child:const Text('Vérifier ma réponse')),if(checked)Text('${choice==u.answer?'Bonne réponse ! ':'À revoir. Bonne réponse : ${u.options[u.answer]}. '}${u.explanation}',style:TextStyle(fontWeight:FontWeight.w600,color:choice==u.answer?Colors.green.shade800:Theme.of(context).colorScheme.error)),if(checked)TextButton(onPressed:()=>setState((){choice=null;checked=false;}),child:const Text('Recommencer'))]))]));}}
